// Shared permit for explicitly implemented edit adapters. No route/core changes here.
using System;using System.Collections;using System.Collections.Generic;using System.Diagnostics;
using System.Globalization;using System.IO;using System.Security.Cryptography;using System.Text;
using System.Web.Script.Serialization;
namespace McgsInternalBridge {
 internal static partial class NativeUsableEditPermit {
  internal static bool IsStrategyCreation(string kind){return kind=="strategy-create-user"||kind=="strategy-create"||kind=="strategy-copy";}
  internal const string Purpose="native-usable-edit-batch";
  internal static string DirectoryRoot{get{return Path.GetFullPath(Path.Combine(NativeOperations.TaskRoot,"coverage-20261101","usable-edit-0001"));}}
  internal static string Fixture{get{return NativeEngineeringProjectScope.ExpectedProjectPath;}}
  internal static string Json(object v){return new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue,RecursionLimit=256}.Serialize(v);}
  internal static string Digest(object v){using(var h=SHA256.Create())return Hex(h.ComputeHash(Encoding.UTF8.GetBytes(Json(v))));}
  static string Hex(byte[] b){return BitConverter.ToString(b).Replace("-","").ToLowerInvariant();}
  internal static Dictionary<string,object> Map(object v){return (Dictionary<string,object>)v;}
  internal static bool SamePath(string a,string b){return NativeEngineeringProjectScope.SameFile(a,b);}
  internal static void Require(bool b,string m){NativeMemory.Require(b,m);}
  internal static string Ordinary(string file){string p=Path.GetFullPath(file),root=DirectoryRoot.TrimEnd('\\')+"\\";Require(p.StartsWith(root,StringComparison.OrdinalIgnoreCase)&&File.Exists(p)&&(File.GetAttributes(p)&(FileAttributes.Directory|FileAttributes.ReparsePoint))==0,"Permit must be a regular file inside usable-edit-0001.");CheckAncestors(Path.GetDirectoryName(p));return p;}
  static void CheckAncestors(string directory){string root=Path.GetFullPath(NativeOperations.TaskRoot).TrimEnd('\\');for(var d=new DirectoryInfo(directory);d!=null&&d.FullName.StartsWith(root,StringComparison.OrdinalIgnoreCase);d=d.Parent)if(d.Exists)Require((d.Attributes&FileAttributes.ReparsePoint)==0,"Permit/claim ancestor is a reparse point.");}
  static string Text(Dictionary<string,object> d,string k){object v;Require(d.TryGetValue(k,out v)&&v is string,"Permit string missing: "+k);return (string)v;}
  static string HashString(Dictionary<string,object> d,string k){string s=Text(d,k);Require(s.Length==64,"Permit SHA length differs: "+k);foreach(char c in s)Require((c>='0'&&c<='9')||(c>='a'&&c<='f'),"Permit SHA must be lower hex.");return s;}
  internal static Dictionary<string,object> Capture(NativeEngine engine,NativeContext context){
   return CaptureIdentity(engine,context);
  }
  internal static Plan LoadPlan(Dictionary<string,object> request,NativeEngine engine,NativeContext context,Dictionary<string,object> currentSummary,IEnumerable<string> implementedKinds){return new Plan(request,engine,context,currentSummary,implementedKinds);}
  internal static Plan LoadDirectPlan(Dictionary<string,object> document,NativeEngine engine,NativeContext context,Dictionary<string,object> summary,IEnumerable<string> kinds){return new Plan(new Dictionary<string,object>{{"expected_project",Fixture}},engine,context,summary,kinds,document);}
  internal sealed class Plan {
   internal readonly List<Dictionary<string,object>> Actions=new List<Dictionary<string,object>>();
   internal readonly Dictionary<string,object> Document,BeforeSummary;
   internal readonly string PermitSha,PermitFile,ProjectSha,SummarySha,ClaimFile;
   internal readonly bool Commit,RootSaveAllowed;internal readonly bool Direct;readonly bool mainControlSaveAllowed,linguistSaveAllowed;
   readonly HashSet<int> savePages=new HashSet<int>(),saveStrategies=new HashSet<int>(),saveModules=new HashSet<int>();
   readonly HashSet<string> createdPageActions=new HashSet<string>(StringComparer.Ordinal),createdStrategyActions=new HashSet<string>(StringComparer.Ordinal);
   readonly NativeEngine engine;readonly NativeContext context;readonly IntPtr root;
   readonly int pid,thread;readonly long creation;readonly Dictionary<string,string> actionHashes=new Dictionary<string,string>(StringComparer.Ordinal);
   internal bool ClaimCallEntered,ClaimCallReturned;
   internal Plan(Dictionary<string,object> request,NativeEngine e,NativeContext c,Dictionary<string,object> summary,IEnumerable<string> kinds,Dictionary<string,object> directDocument=null){
    Direct=directDocument!=null;engine=e;context=c;pid=Process.GetCurrentProcess().Id;creation=Process.GetCurrentProcess().StartTime.ToFileTimeUtc();thread=NativeMemory.GetCurrentThreadId();root=NativeMemory.Ptr(engine.Address(0xFBB578),0x520);BeforeSummary=summary;
    if(Direct){PermitFile=null;Document=directDocument;PermitSha=Digest(Document);}else{PermitFile=Ordinary(Text(request,"permit_file"));PermitSha=HashString(request,"permit_sha256");Require(NativeMemory.Hash(PermitFile)==PermitSha,"Permit file SHA differs.");
    Document=new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue,RecursionLimit=256}.Deserialize<Dictionary<string,object>>(File.ReadAllText(PermitFile,Encoding.UTF8));}
    Require(Convert.ToInt32(Document["schema"])==1&&Text(Document,"purpose")==Purpose,"Permit schema/purpose differs.");Guid trial;Require(Guid.TryParse(Text(Document,"trial_id"),out trial),"Permit needs a unique trial_id.");
    Require(Convert.ToInt32(Document["process_id"])==pid&&Convert.ToInt64(Document["creation_filetime"])==creation&&Convert.ToInt32(Document["ui_thread_id"])==thread,"Permit PID/creation/UI differs.");
    Require(SamePath(Text(Document,"project_path"),Fixture)&&SamePath(Text(request,"expected_project"),Fixture),"Permit is not the current owned fixture.");
    Require(HashString(Document,"editor_image_sha256")==engine.ImageSha256,"Permit editor ABI image differs.");
    ProjectSha=HashString(Document,"project_sha256");SummarySha=HashString(Document,"native_summary_utf8_sha256");Require(ProjectSha==Convert.ToString(summary["disk_sha256"])&&NativeMemory.Hash(Fixture)==ProjectSha&&Digest(summary)==SummarySha,"Permit storage/native summary preimage differs.");
    Require(Document["commit"] is bool,"Permit commit must be Boolean.");Commit=(bool)Document["commit"];var saves=Map(Document["save_scope"]);Require(saves["root_save"] is bool,"Root-save scope must be Boolean.");RootSaveAllowed=(bool)saves["root_save"];object mainControl;if(saves.TryGetValue("main_control_document",out mainControl)){Require(mainControl is bool,"main_control_document scope must be Boolean.");mainControlSaveAllowed=(bool)mainControl;}object linguist;if(saves.TryGetValue("linguist_document",out linguist)){Require(linguist is bool,"linguist_document scope must be Boolean.");linguistSaveAllowed=(bool)linguist;}Require(Commit||!RootSaveAllowed,"commit=false cannot authorize RootSave.");foreach(object id in (IEnumerable)saves["affected_page_ids"]){int n=Convert.ToInt32(id);Require(n>=0&&savePages.Add(n),"Invalid/duplicate save page ID.");}foreach(object id in (IEnumerable)saves["strategy_ids"]){int n=Convert.ToInt32(id);Require(n>=0&&saveStrategies.Add(n),"Invalid/duplicate save strategy ID.");}
    var implemented=new HashSet<string>(kinds,StringComparer.Ordinal);Require(implemented.Count>0,"Batch has no implemented adapters.");var ids=new HashSet<string>(StringComparer.Ordinal);
    object moduleScope;if(saves.TryGetValue("module_ids",out moduleScope))foreach(object id in (IEnumerable)moduleScope){int n=Convert.ToInt32(id);Require(n>=0&&n<=63&&saveModules.Add(n),"Invalid/duplicate native service module ID.");}
    foreach(object v in (IEnumerable)Document["actions"]){var a=Map(v);string id=Text(a,"action_id"),kind=Text(a,"kind");Require(id.Length>0&&id.Length<=96&&ids.Add(id)&&implemented.Contains(kind),"Duplicate action_id or unimplemented action kind.");Map(a["target"]);Map(a["before"]);Map(a["after"]);HashString(a,"abi_profile_sha256");Actions.Add(a);actionHashes.Add(id,Digest(a));}
    object created;if(saves.TryGetValue("created_page_actions",out created))foreach(object id in(IEnumerable)created)Require(id is string&&createdPageActions.Add((string)id),"Created-page action IDs must be unique strings.");if(saves.TryGetValue("created_strategy_actions",out created))foreach(object id in(IEnumerable)created)Require(id is string&&createdStrategyActions.Add((string)id),"Created-strategy action IDs must be unique strings.");
    foreach(var a in Actions){string id=Text(a,"action_id"),kind=Text(a,"kind");if(kind=="page-create"||kind=="page-copy")Require(createdPageActions.Contains(id),"Page creation/copy needs its hashed created_page_actions entry before native mutation.");if(IsStrategyCreation(kind))Require(createdStrategyActions.Contains(id),"Strategy creation needs its hashed created_strategy_actions entry.");}
    foreach(string id in createdPageActions){bool match=false;foreach(var a in Actions)if(Text(a,"action_id")==id&&(Text(a,"kind")=="page-create"||Text(a,"kind")=="page-copy"))match=true;Require(match,"created_page_actions references a noncreation action.");}foreach(string id in createdStrategyActions){bool match=false;foreach(var a in Actions)if(Text(a,"action_id")==id&&IsStrategyCreation(Text(a,"kind")))match=true;Require(match,"created_strategy_actions references a noncreation action.");}
    Require(Actions.Count>0,"Batch has no edit actions.");if(Direct){ClaimFile=null;}else{ClaimFile=Path.Combine(DirectoryRoot,"claims","edit-"+pid+"-"+creation+"-"+PermitSha+".json");CheckAncestors(Path.GetDirectoryName(ClaimFile));Require(!File.Exists(ClaimFile)&&!Directory.Exists(ClaimFile),"Permit already has a permanent claim; do not replay.");}RequireCurrent();
   }
   internal void RequireCurrent(){Require(IntPtr.Size==4&&EngineEntry.ExpectedUiThreadId==thread&&NativeMemory.GetCurrentThreadId()==thread&&Process.GetCurrentProcess().Id==pid&&Process.GetCurrentProcess().StartTime.ToFileTimeUtc()==creation,"Permit process/UI changed.");Require(NativeMemory.Ptr(engine.Address(0xFBB578),0x520)==root&&NativeMemory.Ptr(root,0)==engine.Address(0xD57684)&&NativeMemory.Ptr(root,0x2D4)==context.ObjectModel,"Permit native root/model changed.");Require(SamePath(NativeStrategyProfile.ReadBorrowedCString(NativeMemory.Add(root,0x24),2048),Fixture),"Permit current project changed.");}
   internal int[] RootFlags(){RequireCurrent();return new[]{NativeMemory.I32(root,0x48),NativeMemory.I32(root,0x114)};}
   internal string CheckAction(Dictionary<string,object> action){string id=Text(action,"action_id"),expected;Require(actionHashes.TryGetValue(id,out expected)&&Digest(action)==expected,"Action content differs from the immutable permit.");return id;}
   internal void RequireSaveScope(Dictionary<string,object> action,Dictionary<string,int> newPages,Dictionary<string,int> newStrategies){if(Direct){CheckAction(action);return;}Require(Commit,"This permit does not authorize explicit persistence.");string actionId=CheckAction(action),kind=Text(action,"kind");if(kind=="reference-sync"){var syncTarget=Map(action["target"]);int total=0;foreach(string key in new[]{"page_ids","strategy_ids"}){Require(syncTarget.ContainsKey(key),"Reference sync requires both explicit owner ID arrays.");var seen=new HashSet<int>();foreach(object raw in (IEnumerable)syncTarget[key]){int owner=Convert.ToInt32(raw);Require(owner>=0&&seen.Add(owner)&&++total<=Int32.MaxValue,"Reference sync owner IDs repeat or exceed the bounded scope.");if(key=="page_ids")RequireRelatedPagePersistence(action,owner);else RequireRelatedStrategyPersistence(action,owner);}}Require(total>0,"Reference sync needs at least one owner.");return;}if(kind.StartsWith("language-",StringComparison.Ordinal)){RequireLinguistPersistence(action);return;}if(kind=="main-control-flush"){RequireMainControlPersistence(action);return;}if(kind=="root-flush"){Require(RootSaveAllowed,"Root flush is outside hashed save_scope.");return;}if(kind=="page-create"||kind=="page-copy"){Require(createdPageActions.Contains(actionId)&&newPages.ContainsKey(actionId),"Created page identity was not verified/registered.");return;}if(IsStrategyCreation(kind)){Require(createdStrategyActions.Contains(actionId)&&newStrategies.ContainsKey(actionId),"Created strategy identity was not verified/registered.");return;}var target=Map(action["target"]);object id;if(target.TryGetValue("module_id",out id)){Require(saveModules.Contains(Convert.ToInt32(id)),"Native service module flush is outside hashed save_scope.");return;}if(target.TryGetValue("page_id",out id)){Require(savePages.Contains(Convert.ToInt32(id)),"Page flush is outside hashed save_scope.");return;}if(target.TryGetValue("strategy_id",out id)||target.TryGetValue("block_id",out id)){Require(saveStrategies.Contains(Convert.ToInt32(id)),"Strategy flush is outside hashed save_scope.");return;}throw new InvalidOperationException("Adapter must expose a scoped page_id/strategy_id before persistence.");}
   internal void CheckCreated(Dictionary<string,object> action,int nativeId,bool page){string id=CheckAction(action),kind=Text(action,"kind");Require(nativeId>=0&&(page?createdPageActions.Contains(id)&&(kind=="page-create"||kind=="page-copy"):createdStrategyActions.Contains(id)&&IsStrategyCreation(kind)),"Creation ID binding is outside the hashed action whitelist.");if(!page){object expected;var t=Map(action["target"]);if(t.TryGetValue("expected_next_block_id",out expected))Require(Convert.ToInt32(expected)==nativeId,"Native new strategy ID differs from the hashed next-ID preimage.");}}
   internal void ValidatePersistenceScopesBeforeClaim(){if(Direct)return;Require(!ClaimCallEntered,"Persistence scopes must be checked before Claim.");if(!Commit)return;var empty=new Dictionary<string,int>(StringComparer.Ordinal);foreach(var a in Actions){string kind=Text(a,"kind"),id=CheckAction(a);if(kind=="page-create"||kind=="page-copy")Require(createdPageActions.Contains(id),"Created-page save permission missing.");else if(IsStrategyCreation(kind))Require(createdStrategyActions.Contains(id),"Created-strategy save permission missing.");else RequireSaveScope(a,empty,empty);}}
   internal void RequireModulePersistence(Dictionary<string,object> action,int id){CheckAction(action);if(Direct){Require(id>=0,"Negative native owner ID.");return;}Require(Commit&&saveModules.Contains(id),"Native service module persistence is outside hashed save_scope.");}
   internal void RequireRelatedPagePersistence(Dictionary<string,object> action,int id){CheckAction(action);if(Direct){Require(id>=0,"Negative native owner ID.");return;}Require(Commit&&savePages.Contains(id),"Related page persistence is outside hashed save_scope.");}
   internal void RequireRelatedStrategyPersistence(Dictionary<string,object> action,int id){CheckAction(action);if(Direct){Require(id>=0,"Negative native owner ID.");return;}Require(Commit&&saveStrategies.Contains(id),"Related strategy persistence is outside hashed save_scope.");}
   internal void RequireMainControlPersistence(Dictionary<string,object> action){CheckAction(action);if(Direct){return;}Require(Commit&&mainControlSaveAllowed,"Main-control document persistence is outside hashed save_scope.");}
   internal void RequireLinguistPersistence(Dictionary<string,object> action){CheckAction(action);if(Direct){return;}Require(Commit&&linguistSaveAllowed,"Linguist document persistence is outside hashed save_scope.");}
   internal Lease Claim(Action finalPreimageCheck){
    Require(!ClaimCallEntered,"This Plan already entered execution; no automatic retry.");if(Direct){RequireCurrent();finalPreimageCheck();foreach(var a in Actions)CheckAction(a);RequireCurrent();ClaimCallEntered=true;ClaimCallReturned=true;return new Lease(this); }ValidatePersistenceScopesBeforeClaim();RequireCurrent();finalPreimageCheck();var current=Capture(engine,context);Require(Digest(current)==SummarySha&&NativeMemory.Hash(Fixture)==ProjectSha,"Native preimage changed after preparation.");Require(Ordinary(PermitFile)==PermitFile&&NativeMemory.Hash(PermitFile)==PermitSha,"Permit changed after preparation.");foreach(var a in Actions)CheckAction(a);RequireCurrent();
    CheckAncestors(Path.GetDirectoryName(ClaimFile));Directory.CreateDirectory(Path.GetDirectoryName(ClaimFile));CheckAncestors(Path.GetDirectoryName(ClaimFile));
    byte[] bytes=Encoding.UTF8.GetBytes(Json(new Dictionary<string,object>{{"schema",1},{"purpose",Purpose},{"permit_sha256",PermitSha},{"process_id",pid},{"creation_filetime",creation},{"ui_thread_id",thread},{"native_calls_must_not_be_automatically_repeated",true}}));
    ClaimCallEntered=true;using(var file=new FileStream(ClaimFile,FileMode.CreateNew,FileAccess.Write,FileShare.Read,4096,FileOptions.WriteThrough)){file.Write(bytes,0,bytes.Length);file.Flush(true);}Require(Hex(File.ReadAllBytes(ClaimFile))==Hex(bytes),"Durable permit claim readback differs; do not retry.");ClaimCallReturned=true;return new Lease(this);
   }
   internal Dictionary<string,object> ClaimStatus(){return new Dictionary<string,object>{{"execution_mode",Direct?"direct":"legacy-permit"},{"permit_file_required",!Direct},{"durable_permit_claim_used",!Direct},{"permit_file",PermitFile},{"permit_sha256",Direct?null:PermitSha},{"claim_file",ClaimFile},{"claim_call_entered",ClaimCallEntered},{"claim_completed_returned",ClaimCallReturned},{"claim_state_ambiguous_or_partial_possible",ClaimCallEntered&&!ClaimCallReturned},{"automatic_retry",false},{"automatic_rollback",false}};}
  }
  internal sealed class Lease {
   readonly Plan plan;readonly Dictionary<string,int> stages=new Dictionary<string,int>(StringComparer.Ordinal);readonly Dictionary<string,int> createdPages=new Dictionary<string,int>(StringComparer.Ordinal),createdStrategies=new Dictionary<string,int>(StringComparer.Ordinal);bool rootSaveEntered,rootSaveComplete;int expectedRootDirty,expectedRootCompile;string activeAction,activePhase;HashSet<string> activeFlushGroup;
   internal Lease(Plan p){plan=p;foreach(var a in p.Actions)stages.Add(p.CheckAction(a),0);UpdateBoundary();}
   void UpdateBoundary(){int[] flags=plan.RootFlags();expectedRootDirty=flags[0];expectedRootCompile=flags[1];}
   void Boundary(){RequireCurrent();Require(activeAction==null,"A prior native phase has not verified completion; do not continue the batch.");int[] flags=plan.RootFlags();Require(flags[0]==expectedRootDirty&&flags[1]==expectedRootCompile,"Root dirty/compile state drifted between authorized native phases.");}
   internal void RequireCurrent(){Require(plan.ClaimCallReturned,"Execution context has not started.");plan.RequireCurrent();}
   internal void BeginApply(Dictionary<string,object> action){Boundary();string id=plan.CheckAction(action);Require(stages[id]==0,"Action already entered Apply; unknown results are not replayed.");stages[id]=1;activeAction=id;activePhase="apply";}
   internal void RequireApplying(Dictionary<string,object> action){RequireCurrent();Require(stages[plan.CheckAction(action)]==1,"Action is not in its claimed Apply phase.");}
   internal void CompleteApply(Dictionary<string,object> action){RequireApplying(action);string id=plan.CheckAction(action);Require(activeAction==id&&activePhase=="apply","Apply completion belongs to another active action.");stages[id]=2;UpdateBoundary();activeAction=null;activePhase=null;}
   internal void RegisterCreatedPage(Dictionary<string,object> action,int nativeId){RequireApplying(action);plan.CheckCreated(action,nativeId,true);string id=plan.CheckAction(action);Require(!createdPages.ContainsKey(id)&&!createdPages.ContainsValue(nativeId),"Created page ID was already registered.");createdPages.Add(id,nativeId);}
   internal void RegisterCreatedStrategy(Dictionary<string,object> action,int nativeId){RequireApplying(action);plan.CheckCreated(action,nativeId,false);string id=plan.CheckAction(action);Require(!createdStrategies.ContainsKey(id)&&!createdStrategies.ContainsValue(nativeId),"Created strategy ID was already registered.");createdStrategies.Add(id,nativeId);}
   internal void RequirePersistencePermission(Dictionary<string,object> action){RequireCurrent();plan.RequireSaveScope(action,createdPages,createdStrategies);}
   internal void RequireModulePersistence(Dictionary<string,object> action,int id){RequireCurrent();string actionId=plan.CheckAction(action);Require(stages[actionId]==1||stages[actionId]==3,"Module persistence requires the action active Apply/Flush.");Require(activeAction==actionId||(activePhase=="flush-group"&&activeFlushGroup!=null&&activeFlushGroup.Contains(actionId)),"Module persistence belongs to another active action.");plan.RequireModulePersistence(action,id);}
   internal void RequireRelatedPagePersistence(Dictionary<string,object> action,int id){RequireCurrent();string actionId=plan.CheckAction(action);Require(stages[actionId]==1||stages[actionId]==3,"Related persistence requires the action's active Apply/Flush.");Require(activeAction==actionId||(activePhase=="flush-group"&&activeFlushGroup!=null&&activeFlushGroup.Contains(actionId)),"Related page persistence belongs to another active action.");plan.RequireRelatedPagePersistence(action,id);}
   internal void RequireRelatedStrategyPersistence(Dictionary<string,object> action,int id){RequireCurrent();string actionId=plan.CheckAction(action);Require(stages[actionId]==1||stages[actionId]==3,"Related persistence requires the action's active Apply/Flush.");Require(activeAction==actionId||(activePhase=="flush-group"&&activeFlushGroup!=null&&activeFlushGroup.Contains(actionId)),"Related strategy persistence belongs to another active action.");plan.RequireRelatedStrategyPersistence(action,id);}
   internal void RequireMainControlPersistence(Dictionary<string,object> action){RequireCurrent();string id=plan.CheckAction(action);Require((stages[id]==1||stages[id]==3)&&(activeAction==id||(activePhase=="flush-group"&&activeFlushGroup!=null&&activeFlushGroup.Contains(id))),"Main-control persistence requires its active Apply/Flush action.");plan.RequireMainControlPersistence(action);}
   internal void RequireLinguistPersistence(Dictionary<string,object> action){RequireCurrent();string id=plan.CheckAction(action);Require((stages[id]==1||stages[id]==3)&&(activeAction==id||(activePhase=="flush-group"&&activeFlushGroup!=null&&activeFlushGroup.Contains(id))),"Linguist persistence requires its active Apply/Flush action.");plan.RequireLinguistPersistence(action);}
   internal void BeginFlush(Dictionary<string,object> action){Boundary();RequirePersistencePermission(action);string id=plan.CheckAction(action);Require(stages[id]==2,"Only a verified Apply may enter Flush once.");stages[id]=3;activeAction=id;activePhase="flush";}
   internal void RequireFlushing(Dictionary<string,object> action){RequireCurrent();Require(stages[plan.CheckAction(action)]==3,"Action is not in Flush phase.");}
   internal void CompleteFlush(Dictionary<string,object> action){RequireFlushing(action);string id=plan.CheckAction(action);Require(activeAction==id&&activePhase=="flush","Flush completion belongs to another active action.");stages[id]=4;UpdateBoundary();activeAction=null;activePhase=null;}
   List<Dictionary<string,object>> FlushGroup(IEnumerable<Dictionary<string,object>> actions){var list=new List<Dictionary<string,object>>();var ids=new HashSet<string>(StringComparer.Ordinal);foreach(var action in actions){Require(ids.Add(plan.CheckAction(action)),"Duplicate flush-group action.");list.Add(action);}Require(list.Count>0,"Empty flush group.");return list;}
   internal void BeginFlushGroup(IEnumerable<Dictionary<string,object>> actions){Boundary();var list=FlushGroup(actions);foreach(var a in list){RequirePersistencePermission(a);Require(stages[plan.CheckAction(a)]==2,"Flush-group requires every action Apply verified.");}activeFlushGroup=new HashSet<string>(StringComparer.Ordinal);foreach(var a in list){string id=plan.CheckAction(a);stages[id]=3;activeFlushGroup.Add(id);}activeAction="$flush-group";activePhase="flush-group";}
   internal void RequireFlushingGroup(IEnumerable<Dictionary<string,object>> actions){RequireCurrent();Require(activePhase=="flush-group"&&activeFlushGroup!=null,"No active flush group.");var list=FlushGroup(actions);var ids=new HashSet<string>(StringComparer.Ordinal);foreach(var a in list){string id=plan.CheckAction(a);Require(stages[id]==3,"Flush-group phase differs.");ids.Add(id);}Require(ids.SetEquals(activeFlushGroup),"Flush-group membership changed.");}
   internal void CompleteFlushGroup(IEnumerable<Dictionary<string,object>> actions){RequireFlushingGroup(actions);foreach(string id in activeFlushGroup)stages[id]=4;UpdateBoundary();activeFlushGroup=null;activeAction=null;activePhase=null;}
   internal void RequireCompleteForCommit(){Boundary();Require(plan.Commit&&plan.RootSaveAllowed,"RootSave is outside hashed commit/save_scope.");foreach(int stage in stages.Values)Require(stage==4,"Every action must have verified Apply/Flush before batch commit.");}
   internal void BeginRootSave(){RequireCompleteForCommit();Require(!rootSaveEntered,"RootSave already entered; do not repeat unknown results.");rootSaveEntered=true;activeAction="$root-save";activePhase="root-save";}
   internal void CompleteRootSave(){RequireCurrent();Require(rootSaveEntered&&!rootSaveComplete&&activeAction=="$root-save"&&activePhase=="root-save","RootSave completion phase differs.");rootSaveComplete=true;UpdateBoundary();activeAction=null;activePhase=null;}
   internal Dictionary<string,object> Status(){var r=plan.ClaimStatus();r["action_stages"]=new Dictionary<string,int>(stages);r["created_page_ids"]=new Dictionary<string,int>(createdPages);r["created_strategy_ids"]=new Dictionary<string,int>(createdStrategies);r["commit_authorized"]=plan.Commit;r["root_save_entered"]=rootSaveEntered;r["root_save_complete"]=rootSaveComplete;r["expected_root_modified"]=expectedRootDirty;r["expected_root_compile_raw"]=expectedRootCompile;r["active_action"]=activeAction;r["active_phase"]=activePhase;return r;}
  }
 }
